'use strict';

// MODULES //

var isSignalReference = require( '@stdlib/plot/vega/base/assert/is-signal-reference' );
var isUndefined = require( '@stdlib/assert/is-undefined' );
var contains = require( '@stdlib/array/base/assert/contains' ).factory;
var copyJSON = require( './../../utils/copy_json.js' );
var signalName = require( './../../utils/signal_name.js' );


// VARIABLES //

var PROPS = [
	'orient',
	'type'
];

// Define a list of properties which need to be made explicitly "undefined" when set to falsy values:
var SPECIAL_PROPS = [
	'direction'
];
var isSpecialProp = contains( SPECIAL_PROPS );


// MAIN //

/**
* Returns a transformed legend schema containing signals for use in conjunction with UI components.
*
* ## Notes
*
* -   The function mutates the provided list of signals.
*
* @private
* @param {Object} schema - legend schema
* @param {Array} signals - list of signals
* @param {Object} defaults - legend schema defaults
* @param {string} prefix - signal prefix
* @returns {Object} transformed schema
*/
function transform( schema, signals, defaults, prefix ) {
	var value;
	var name;
	var out;
	var k;
	var v;
	var i;

	out = copyJSON( schema );
	for ( i = 0; i < PROPS.length; i++ ) {
		k = PROPS[ i ];
		v = schema[ k ];
		if ( !isSignalReference( v ) ) {
			name = signalName( prefix+k );
			value = ( isUndefined( v ) ) ? defaults[ k ].default : v;

			if ( isSpecialProp( k ) ) {
				if ( isUndefined( v ) || v === '' || v === false ) {
					out[ k ] = void 0;
					signals.push({
						'name': name,
						'value': void 0
					});

					// Skip further processing...
					continue;
				}
			}
			signals.push({
				'name': name,
				'value': value
			});
			out[ k ] = value;
		}
	}
	return out;
}


// EXPORTS //

module.exports = transform;
